-- PostgreSQL Database Schema for Moroccan Students
-- This script creates a users table and seeds it with 100 Moroccan students

-- Create users table
-- Create users table
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  username VARCHAR(120) UNIQUE NOT NULL,
  email VARCHAR(120) UNIQUE NOT NULL,
  password VARCHAR(255) NOT NULL,
  first_name VARCHAR(100),
  last_name VARCHAR(100),
  phone VARCHAR(20),
  student_id VARCHAR(50) UNIQUE,
  university VARCHAR(150),
  field_of_study VARCHAR(150),
  enrollment_year INTEGER,
  city VARCHAR(100),
  region VARCHAR(100),
  date_of_birth DATE,
  gender VARCHAR(10),
  account_status VARCHAR(20) DEFAULT 'active',
  role VARCHAR(20) DEFAULT 'user',
  level INTEGER DEFAULT 1,
  xp INTEGER DEFAULT 500,
  onboarding_done BOOLEAN DEFAULT true,
  onboarding_rejected BOOLEAN DEFAULT false,
  is_blocked BOOLEAN DEFAULT false,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create indexes for better query performance
CREATE INDEX idx_email ON users(email);
CREATE INDEX idx_student_id ON users(student_id);
CREATE INDEX idx_university ON users(university);
CREATE INDEX idx_city ON users(city);

